/* ============================================
   FIGURE COMPONENT
   Image + caption in a rounded container.
   Pass onClick for a zoomable (lightbox) figure.
   ============================================ */

.ds-figure {
  margin: 0;
  border-radius: var(--radius-300);
  overflow: hidden;
  background-color: var(--color-bg-container-secondary);
}

/* ============================================
   MEDIA — child img/picture fills the width
   ============================================ */

.ds-figure__media {
  display: block;
  line-height: 0;
}

.ds-figure__media img {
  width: 100%;
  height: auto;
  display: block;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

/* ============================================
   CAPTION
   ============================================ */

.ds-figure__caption {
  display: block;
  padding: var(--padding-400) var(--padding-500);
  border-top: var(--border-025) solid var(--color-bg-container-border);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
}

/* ============================================
   ZOOMABLE (has onClick)
   ============================================ */

/* The zoom control is a real <button> wrapping the media (ARIA forbids
   role="button" on <figure>), stripped back to a bare block. */
.ds-figure__zoom {
  display: block;
  width: 100%;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  cursor: zoom-in;
}

.ds-figure__zoom:hover .ds-figure__media img {
  opacity: 0.88;
}

/* Inset ring: the button sits inside the figure's overflow clip, so an
   outset outline would be cropped away. */
.ds-figure__zoom:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
}

import React from 'react';
import './Figure.css';

export interface FigureProps {
  /** The image element — a plain <img> or a framework image component */
  children: React.ReactNode;
  /** Caption rendered below the image */
  caption?: React.ReactNode;
  /** Click handler (e.g. open a lightbox) — adds zoom affordance + keyboard support */
  onClick?: () => void;
  /** Additional CSS classes */
  className?: string;
}

/**
 * Figure component — an image with an optional caption in a bordered,
 * rounded container. Pass onClick to make it zoomable (adds the
 * zoom cursor, hover dim, and keyboard activation).
 */
export const Figure = ({
  children,
  caption,
  onClick,
  className = '',
}: FigureProps) => {
  const baseClass = 'ds-figure';

  const classes = [baseClass, onClick && `${baseClass}--zoomable`, className]
    .filter(Boolean)
    .join(' ');

  const media = <div className={`${baseClass}__media`}>{children}</div>;

  return (
    <figure className={classes}>
      {onClick ? (
        // A real button rather than role="button" on the figure: ARIA
        // forbids the button role on <figure>, and the element brings
        // Enter/Space activation itself. Its accessible name is the
        // child image's alt text.
        <button type="button" className={`${baseClass}__zoom`} onClick={onClick}>
          {media}
        </button>
      ) : (
        media
      )}
      {caption && (
        <figcaption className={`${baseClass}__caption`}>{caption}</figcaption>
      )}
    </figure>
  );
};
